            if (Number.isFinite(available) && available < floor) {
                breach(`stopped: host memory below the floor (${gib(available)} available, ${gib(floor)} required)`);
                return;
            }
            schedule();
        };
        schedule();
        return () => {
            cancelled = true;
            clearTimeout(timer);
        };
    }

"""
